}

bool ucl_parser_add_string(struct ucl_parser *parser, const char *data,
						   size_t len)
{
	if (parser == NULL) {
		return false;
	}

	return ucl_parser_add_string_priority(parser,
										  (const unsigned char *) data, len, parser->default_priority);
}

