	void (*ucl_emitter_start_array)(struct ucl_emitter_context *ctx,
									const ucl_object_t *obj, bool first, bool print_key);
	void (*ucl_emitter_end_array)(struct ucl_emitter_context *ctx,
								  const ucl_object_t *obj);
};

