unsigned int
ucl_array_index_of(ucl_object_t *top, ucl_object_t *elt)
{
	if (top->type != UCL_ARRAY) {
		return (unsigned int) (-1);
	}

	UCL_ARRAY_GET(vec, top);
	unsigned i;

	if (vec == NULL) {
		return (unsigned int) (-1);
	}

	for (i = 0; i < vec->n; i++) {
		if (kv_A(*vec, i) == elt) {
			return i;
		}
	}

	return (unsigned int) (-1);
}

ucl_object_t *
ucl_array_replace_index(ucl_object_t *top, ucl_object_t *elt,
						unsigned int index)
