ucl_object_t *
ucl_array_pop_last(ucl_object_t *top)
{
	if (top->type != UCL_ARRAY) {
		return NULL;
	}

	UCL_ARRAY_GET(vec, top);
	ucl_object_t **obj, *ret = NULL;

	if (vec != NULL && vec->n > 0) {
		obj = &kv_A(*vec, vec->n - 1);
		ret = *obj;
		kv_del(ucl_object_t *, *vec, vec->n - 1);
		top->len--;
