	if (vec != NULL && vec->n > 0 && index < vec->n) {
		ret = kv_A(*vec, index);
		kv_A(*vec, index) = elt;
	}

	return ret;
}

ucl_object_t *
ucl_elt_append(ucl_object_t *head, ucl_object_t *elt)
{

	if (head == NULL) {
		elt->next = NULL;
		elt->prev = elt;
		head = elt;
	}
	else {
		if (head->type == UCL_USERDATA) {
			/* Userdata objects are VERY special! */
			struct ucl_object_userdata *ud = (struct ucl_object_userdata *) head;
			elt->prev = ud->obj.prev;
			ud->obj.prev->next = elt;
			ud->obj.prev = elt;
			elt->next = NULL;
		}
		else {
			elt->prev = head->prev;
			head->prev->next = elt;
			head->prev = elt;
			elt->next = NULL;
		}
	}

	return head;
}

bool ucl_object_todouble_safe(const ucl_object_t *obj, double *target)
{
	if (obj == NULL || target == NULL) {
		return false;
	}
	switch (obj->type) {
	case UCL_INT:
		*target = obj->value.iv; /* Probably could cause overflow */
		break;
	case UCL_FLOAT:
	case UCL_TIME:
		*target = obj->value.dv;
		break;
	default:
		return false;
	}

	return true;
}

